/**
 * Typed, ready-to-use access to the synthetic Pendo usage dataset.
 *
 * The JSON is generated by scripts/generate-usage-data.mjs and shaped to match
 * demo-hello-app's Pendo payloads exactly (see ./schema.ts). Import the typed
 * arrays directly, or use the selectors for the common demo cuts.
 *
 *   import { visitors, accounts, events, usageSummary } from 'halo-ui-kit/data'
 */
import accountsJson from './accounts.json'
import eventsJson from './events.json'
import type { Account, UsageDataset, UsageEvent, Visitor } from './schema'
import visitorsJson from './visitors.json'

export * from './schema'

export const accounts = accountsJson as Account[]
export const visitors = visitorsJson as Visitor[]
export const events = eventsJson as UsageEvent[]

/** The whole dataset in one object. */
export const usageDataset: UsageDataset = { accounts, visitors, events }

// ---------------------------------------------------------------------------
// Selectors — the common cuts a demo or a dashboard needs
// ---------------------------------------------------------------------------

/** Visitors belonging to a given account. */
export function visitorsForAccount(accountId: string): Visitor[] {
  return visitors.filter((visitor) => visitor.accountId === accountId)
}

/** All events emitted by a given visitor, oldest first. */
export function eventsForVisitor(visitorId: string): UsageEvent[] {
  return events.filter((event) => event.visitorId === visitorId)
}

/** All events for a given account (across all its visitors), oldest first. */
export function eventsForAccount(accountId: string): UsageEvent[] {
  return events.filter((event) => event.accountId === accountId)
}

/** Count of each track-event name across the dataset, highest first. */
export function trackEventCounts(): Array<{ name: string; count: number }> {
  const counts = new Map<string, number>()
  for (const event of events) {
    if (event.type !== 'track') continue
    counts.set(event.name, (counts.get(event.name) ?? 0) + 1)
  }
  return [...counts.entries()]
    .map(([name, count]) => ({ name, count }))
    .sort((a, b) => b.count - a.count)
}

/** Daily event volume, oldest day first — ready for a sparkline/trend chart. */
export function dailyEventVolume(): Array<{ date: string; count: number }> {
  const perDay = new Map<string, number>()
  for (const event of events) {
    const day = event.timestamp.slice(0, 10)
    perDay.set(day, (perDay.get(day) ?? 0) + 1)
  }
  return [...perDay.entries()]
    .map(([date, count]) => ({ date, count }))
    .sort((a, b) => a.date.localeCompare(b.date))
}

/** Headline totals for a KPI strip. */
export function usageSummary(): {
  accounts: number
  visitors: number
  events: number
  trackEvents: number
  pageViews: number
} {
  const trackEvents = events.filter((event) => event.type === 'track').length
  return {
    accounts: accounts.length,
    visitors: visitors.length,
    events: events.length,
    trackEvents,
    pageViews: events.length - trackEvents,
  }
}
